window.__finlexDocLoaded(10223,{"id":10223,"articles":[{"id":1000947,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Defines fair value as an exit price in an orderly transaction between market participants, establishes the 3-level Fair Value Hierarchy (Levels 1, 2, 3), and includes the NAV practical expedient for investment funds.","seq":0},{"id":1000948,"no":"ASC 820-10","heading":"Exit Price, 3-Level Hierarchy & NAV Practical Expedient","text":"• Definition (ASC 820-10-35-2): Exit price in the principal (or most advantageous) market; nonperformance risk incorporated for liabilities.\n• Fair Value Hierarchy (ASC 820-10-35-37): Level 1 (quoted prices in active markets), Level 2 (observable inputs), Level 3 (unobservable inputs — requires quantitative range/weighted-average disclosures and rollforward).\n• NAV Practical Expedient (ASC 820-10-35-59): Permits measuring qualifying investment fund interests at Net Asset Value (NAV) without leveling them in the hierarchy.\n• Contractual Sale Restrictions (ASU 2022-03): Entity-specific contractual restrictions on selling an equity security are NOT considered in measuring its fair value.","seq":1},{"id":1000949,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Substantially converged with IFRS 13, except US GAAP includes the explicit NAV practical expedient (ASC 820-10-35-59) and allows Day-1 gains/losses when fair value is supported by observable/unobservable exit-price evidence (IFRS 9.B5.1.2A strictly defers Day-1 gains unless based solely on observable market data).","seq":2},{"id":1000950,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
